import { createVirtualizer, type Virtualizer, type VirtualWindow } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createContext, For, merge, onCleanup, Show, untrack, useContext } from "solid-js";

import { type PartProps, renderPart, type Render, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** What `render` gets: the props of the scrollport, `data-part` and the caller's class merged in. */
export interface VirtualListPartProps extends PartProps {}

/** The column's props: a `role="list"` whose children are the declared rows and the two spacers. */
export interface VirtualListColumnProps extends VirtualListPartProps {
  readonly role: "list";
  readonly "data-part": string;
  readonly children?: JSX.Element;
}

/** A spacer's props: which end it stands in for, and the height the primitive computed. */
export interface VirtualListSpacerProps extends VirtualListPartProps {
  readonly "data-position": "start" | "end";
  readonly "aria-hidden": "true";
  readonly "data-part": string;
}

/** The window as the part sees it: the declared range, its spacers and the whole content's height. */
export interface VirtualListState {
  readonly window: () => VirtualWindow;
  readonly rangeCount: () => number;
}

export interface VirtualListProps extends Renderable<VirtualListPartProps, VirtualListState> {
  /** The whole list's length: 10 000 rows cost what the screen shows, not 10 000 elements. */
  readonly count: number | (() => number);
  /** Every row's height, px: the primitive's arithmetic window. The skin sets it on the row. */
  readonly itemSize: number;
  /** The scrollport's height, px or a CSS length. @default "24rem" */
  readonly height?: number | string | undefined;
  /** The gap between rows, px, and the column's `row-gap`. @default 0 */
  readonly gap?: number | undefined;
  /** The rows declared either side of the viewport. @default OVERSCAN (2) */
  readonly overscan?: number | undefined;
  /** One row's content: the caller renders the interactive element (its `ref` and `tabindex` are its own). */
  readonly renderItem: (index: number) => JSX.Element;
  /** `render` for the column, which is also the `role="list"`; it gets the rows as `children`. */
  readonly renderColumn?: Render<VirtualListColumnProps, void> | undefined;
  /** `render` for a spacer box; `position` is the end it stands in for. */
  readonly renderSpacer?:
    | ((position: "start" | "end", props: VirtualListSpacerProps) => JSX.Element)
    | undefined;
  readonly class?: string;
  /** The primitive, once: the host's keys call `scrollToIndex` on it, then focus the row it declared. */
  readonly onReady?: (list: Virtualizer) => void;
}

const VirtualListContext = createContext<Virtualizer>();

/**
 * The list's primitive inside a `<VirtualList>`: the host's keys call `scrollToIndex(index)` on it and focus the row
 * once `window()` declares it. Outside a list it is `undefined`.
 */
export const useVirtualList = (): Virtualizer | undefined => useContext(VirtualListContext);

const port = css.cn(
  // The primitive's arithmetic starts at the content's 0, so the scrollport and its column take no padding.
  css.overflow("auto"),
  css.padding("0"),
  css.position("relative"),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.md),
  css.bg(t.color.surface),
  css.fontSize(t.font.size),
  css.color(t.color.text),
);

// One gap-spaced column: the spacers and the rows are its children, and a spacer's height is already the gap short.
const column = css.cn(
  css.display("flex"),
  css.flexDirection("column"),
  css.padding("0"),
  css.margin("0"),
  css.listStyle("none"),
);

const item = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.padding(t.space._1, t.space._3),
  css.boxSizing("border-box"),
  css.overflow("hidden"),
);

const spacerBox = css.cn(css.flexShrink("0"));

const heightOf = (height: number | string): string =>
  typeof height === "number" ? `${height}px` : height;

/**
 * A scrolling list on `createVirtualizer`: the scrollport, the gap-spaced column of rows and the two spacers that stand
 * in for the rows above and below the window, so the scrollbar, the clamp and the content height are the whole list's.
 *
 * **Focus is the item's, and the host owns it.** A row that leaves the window unmounts, so the caller keeps the focus
 * index, calls `scrollToIndex(index)` when its keys move past the window, and focuses its own element only once
 * `window()` declares that index — the list declares the target, the host focuses it. `onReady` (or `useVirtualList()`
 * inside the list) is that accessor; waiting for the declaration is not optional, because a row outside the window has no
 * element to focus yet.
 *
 * Every declared row is a `role="listitem"` with the primitive's `aria-setsize` (the whole count) and `aria-posinset`
 * (index + 1), so a screen reader says "row 4,321 of 10,000" while only a screenful exists. `renderItem` builds only the
 * declared rows: 10 000 rows never build 10 000 elements.
 *
 * A `render` on the scrollport replaces the element; the caller must then call the primitive's `attach` on it (from
 * `onReady` or `useVirtualList()`), or the window never follows the scroll.
 */
export const VirtualList = (props: VirtualListProps): JSX.Element => {
  const list = createVirtualizer({
    count: props.count,
    itemSize: props.itemSize,
    gap: props.gap,
    overscan: props.overscan,
  });
  untrack(() => props.onReady)?.(list);

  let detach: (() => void) | undefined;
  onCleanup(() => detach?.());

  const indexes = (): number[] => {
    const at = list.window();
    return Array.from({ length: Math.max(0, at.last - at.first + 1) }, (_, step) => {
      return at.first + step;
    });
  };

  // A spacer exists only while its height is positive: a zero-height box would still take the column's gap.
  const spacer = (position: "start" | "end"): JSX.Element => {
    const own: VirtualListSpacerProps = {
      "data-part": "virtual-list-spacer",
      "data-position": position,
      "aria-hidden": "true",
      get class() {
        return css.cn(spacerBox);
      },
      get style() {
        return list.spacerProps(position).style;
      },
    };
    return props.renderSpacer === undefined ? <div {...own} /> : props.renderSpacer(position, own);
  };

  const rows = (): JSX.Element => (
    <>
      <Show when={list.window().above > 0}>{spacer("start")}</Show>
      <For each={indexes()}>
        {(index) => (
          <div
            {...list.itemProps(index)}
            role="listitem"
            data-part="virtual-list-item"
            data-index={index}
            class={item}
            style={{ height: `${props.itemSize}px` }}
          >
            {props.renderItem(index)}
          </div>
        )}
      </For>
      <Show when={list.window().below > 0}>{spacer("end")}</Show>
    </>
  );

  // role=list is the column: its children are the two hidden spacers and the declared listitems.
  const body = (): JSX.Element => {
    const own: VirtualListColumnProps = {
      "data-part": "virtual-list-column",
      role: "list",
      get class() {
        return css.cn(column);
      },
      get style() {
        return { "row-gap": `${props.gap ?? 0}px` };
      },
      children: rows(),
    };
    return props.renderColumn === undefined ? <div {...own} /> : props.renderColumn(own, undefined);
  };

  const state: VirtualListState = { window: list.window, rangeCount: list.rangeCount };
  const own = {
    "data-part": "virtual-list",
    get class() {
      return css.cn(port, props.class);
    },
    get style() {
      return { height: heightOf(props.height ?? "24rem") };
    },
  } as PartProps;

  return (
    <VirtualListContext value={list}>
      {renderPart(props, merge(list.scrollProps, own), state, (part) => (
        <div
          {...part}
          ref={(element) => {
            detach = list.attach(element);
          }}
        >
          {body()}
        </div>
      ))}
    </VirtualListContext>
  );
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { flush } from "solid-js";
import { render } from "@solidjs/web";
import { describe, expect, it } from "vite-plus/test";
import type { Virtualizer } from "@cssints/headless";
import { VirtualList } from "./virtual-list.tsx";

// The primitive's window is a memo over the scroll signals; `flush` applies the writes a scroll made.
const ITEM = 36;
const GAP = 4;
const SLOT = ITEM + GAP;

const mountList = (options: { count?: number } = {}) => {
  const root = document.createElement("div");
  document.body.append(root);
  let list: Virtualizer | undefined;
  const dispose = render(
    () => (
      <VirtualList
        count={options.count ?? 10_000}
        itemSize={ITEM}
        gap={GAP}
        height={600}
        onReady={(ready) => {
          list = ready;
        }}
        renderItem={(index) => <span>{`Name ${index + 1}`}</span>}
      />
    ),
    root,
  );
  const port = root.querySelector<HTMLElement>('[data-part="virtual-list"]');
  if (port === null) {
    throw new Error("the list did not mount");
  }
  const rows = (): HTMLElement[] => [
    ...root.querySelectorAll<HTMLElement>('[data-part="virtual-list-item"]'),
  ];
  return {
    root,
    port,
    rows,
    row: (index: number): HTMLElement | undefined =>
      root.querySelector<HTMLElement>(`[data-part="virtual-list-item"][data-index="${index}"]`) ??
      undefined,
    api: (): Virtualizer => {
      if (list === undefined) {
        throw new Error("the list has no primitive");
      }
      return list;
    },
    scrollTo: (top: number): void => {
      port.scrollTop = top;
      port.dispatchEvent(new Event("scroll"));
      flush();
    },
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

const indexes = (rows: ReadonlyArray<HTMLElement>): number[] =>
  rows.map((row) => Number(row.dataset["index"]));

describe("VirtualList skin", () => {
  it("declares a window of 10,000 rows and announces each one's place in the whole set", () => {
    const mounted = mountList();
    const content = 10_000 * ITEM + 9_999 * GAP;

    expect(mounted.port.clientHeight).toBe(600);
    expect(mounted.port.scrollHeight).toBe(content);

    const rows = mounted.rows();
    expect(rows.length).toBeGreaterThan(0);
    expect(rows.length).toBeLessThan(40);
    expect(rows.length).toBe(mounted.api().rangeCount());
    expect(indexes(rows)).toEqual(
      Array.from({ length: rows.length }, (_, step) => mounted.api().window().first + step),
    );

    for (const row of rows) {
      const index = Number(row.dataset["index"]);
      expect(row.getAttribute("role")).toBe("listitem");
      expect(row.getAttribute("aria-setsize")).toBe("10000");
      expect(row.getAttribute("aria-posinset")).toBe(String(index + 1));
      expect(row.offsetTop).toBe(index * SLOT);
      expect(row.textContent).toBe(`Name ${index + 1}`);
    }

    // At the top there is no start spacer: a zero-height box would still add the column's gap.
    expect(
      mounted.root.querySelector('[data-part="virtual-list-spacer"][data-position="start"]'),
    ).toBeNull();
    const end = mounted.root.querySelector<HTMLElement>(
      '[data-part="virtual-list-spacer"][data-position="end"]',
    );
    expect(end?.getAttribute("aria-hidden")).toBe("true");
    expect(end?.offsetHeight).toBe(mounted.api().window().below);
    mounted.dispose();
  });

  it("moves the window with the scroll, re-rendering other rows at their exact offsets", () => {
    const mounted = mountList();
    const top = indexes(mounted.rows());

    mounted.scrollTo(200_000);
    const at = mounted.api().window();
    const middle = indexes(mounted.rows());

    expect(at.first).toBe(4_998);
    expect(middle).not.toEqual(top);
    expect(middle[0]).toBe(at.first);
    for (const row of mounted.rows()) {
      expect(row.offsetTop).toBe(Number(row.dataset["index"]) * SLOT);
    }
    // The start spacer is the rows above the window, gap-compensated: first·slot − gap.
    const start = mounted.root.querySelector<HTMLElement>(
      '[data-part="virtual-list-spacer"][data-position="start"]',
    );
    expect(start?.offsetHeight).toBe(at.above);
    expect(at.above).toBe(at.first * SLOT - GAP);
    expect(mounted.rows()[0]?.offsetTop).toBe(at.above + GAP);
    mounted.dispose();
  });

  it("scrollToIndex reaches a far index and declares it", () => {
    const mounted = mountList();
    expect(mounted.row(9_000)).toBeUndefined();

    mounted.api().scrollToIndex(9_000);
    flush();

    const view = mounted.port.clientHeight;
    expect(mounted.port.scrollTop).toBe(9_000 * SLOT + ITEM - view);
    const row = mounted.row(9_000);
    expect(row).toBeDefined();
    expect(row?.getAttribute("aria-posinset")).toBe("9001");
    expect(row?.getAttribute("aria-setsize")).toBe("10000");
    expect(row?.offsetTop).toBe(9_000 * SLOT);
    mounted.dispose();
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
